        ser = serial.Serial(
            port='/dev/serial0',  # Adjust the port as necessary
            baudrate=9600,
            timeout=2  # Timeout to prevent blocking indefinitely
        )
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

