import sys
from gpiozero import OutputDevice, DigitalOutputDevice
from signal import signal, SIGINT
from contextlib import contextmanager

@contextmanager
def gpio_cleanup(device):
    try:
        yield
    finally:
        if device:
            device.close()

def main():
    try:
        # Initialize the digital output on GPIO 18
        output = DigitalOutputDevice(18)
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

    def handle_exit(signum, frame):
        print("Exiting...")
        sys.exit(0)

    # Register signal handler for clean exit
    signal(SIGINT, handle_exit)

    try:
        with gpio_cleanup(output):
            # Set the output to True (high)
            output.on
            print("GPIO 18 is set to HIGH")

            # Set the output to False (low)
            output.off
            print("GPIO 18 is set to LOW")
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

